'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dlabad = require( './../lib/ndarray.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlabad, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 4', function test( t ) {
	t.strictEqual( dlabad.length, 4, 'returns expected value' );
	t.end();
});

tape( 'the function leaves SMALL and LARGE unchanged (no-op)', function test( t ) {
	var SMALL;
	var LARGE;

	SMALL = new Float64Array( [ 2.2250738585072014e-308 ] );
	LARGE = new Float64Array( [ 1.7976931348623157e+308 ] );

	dlabad( SMALL, 0, LARGE, 0 );

	t.strictEqual( SMALL[ 0 ], 2.2250738585072014e-308, 'SMALL is unchanged' );
	t.strictEqual( LARGE[ 0 ], 1.7976931348623157e+308, 'LARGE is unchanged' );
	t.end();
});

tape( 'the function supports an offset for `SMALL`', function test( t ) {
	var SMALL;
	var LARGE;

	SMALL = new Float64Array( [ 0.0, 2.2250738585072014e-308, 0.0 ] );
	LARGE = new Float64Array( [ 1.7976931348623157e+308 ] );

	dlabad( SMALL, 1, LARGE, 0 );

	t.strictEqual( SMALL[ 0 ], 0.0, 'first element is unchanged' );
	t.strictEqual( SMALL[ 1 ], 2.2250738585072014e-308, 'SMALL at offset is unchanged' );
	t.strictEqual( SMALL[ 2 ], 0.0, 'third element is unchanged' );
	t.strictEqual( LARGE[ 0 ], 1.7976931348623157e+308, 'LARGE is unchanged' );
	t.end();
});

tape( 'the function supports an offset for `LARGE`', function test( t ) {
	var SMALL;
	var LARGE;

	SMALL = new Float64Array( [ 2.2250738585072014e-308 ] );
	LARGE = new Float64Array( [ 0.0, 0.0, 1.7976931348623157e+308 ] );

	dlabad( SMALL, 0, LARGE, 2 );

	t.strictEqual( SMALL[ 0 ], 2.2250738585072014e-308, 'SMALL is unchanged' );
	t.strictEqual( LARGE[ 0 ], 0.0, 'first element is unchanged' );
	t.strictEqual( LARGE[ 1 ], 0.0, 'second element is unchanged' );
	t.strictEqual( LARGE[ 2 ], 1.7976931348623157e+308, 'LARGE at offset is unchanged' );
	t.end();
});

tape( 'the function supports offsets for both `SMALL` and `LARGE`', function test( t ) {
	var SMALL;
	var LARGE;

	SMALL = new Float64Array( [ 0.0, 2.2250738585072014e-308, 0.0 ] );
	LARGE = new Float64Array( [ 0.0, 0.0, 1.7976931348623157e+308 ] );

	dlabad( SMALL, 1, LARGE, 2 );

	t.strictEqual( SMALL[ 0 ], 0.0, 'first element is unchanged' );
	t.strictEqual( SMALL[ 1 ], 2.2250738585072014e-308, 'SMALL at offset is unchanged' );
	t.strictEqual( SMALL[ 2 ], 0.0, 'third element is unchanged' );
	t.strictEqual( LARGE[ 0 ], 0.0, 'first element is unchanged' );
	t.strictEqual( LARGE[ 1 ], 0.0, 'second element is unchanged' );
	t.strictEqual( LARGE[ 2 ], 1.7976931348623157e+308, 'LARGE at offset is unchanged' );
	t.end();
});

tape( 'the function leaves SMALL and LARGE unchanged for various input values', function test( t ) {
	var SMALL;
	var LARGE;

	// Zero values...
	SMALL = new Float64Array( [ 0.0 ] );
	LARGE = new Float64Array( [ 0.0 ] );

	dlabad( SMALL, 0, LARGE, 0 );

	t.strictEqual( SMALL[ 0 ], 0.0, 'SMALL is unchanged' );
	t.strictEqual( LARGE[ 0 ], 0.0, 'LARGE is unchanged' );

	// Typical values...
	SMALL = new Float64Array( [ 1.0e-30 ] );
	LARGE = new Float64Array( [ 1.0e+30 ] );

	dlabad( SMALL, 0, LARGE, 0 );

	t.strictEqual( SMALL[ 0 ], 1.0e-30, 'SMALL is unchanged' );
	t.strictEqual( LARGE[ 0 ], 1.0e+30, 'LARGE is unchanged' );

	// Unit values...
	SMALL = new Float64Array( [ 1.0 ] );
	LARGE = new Float64Array( [ 1.0 ] );

	dlabad( SMALL, 0, LARGE, 0 );

	t.strictEqual( SMALL[ 0 ], 1.0, 'SMALL is unchanged' );
	t.strictEqual( LARGE[ 0 ], 1.0, 'LARGE is unchanged' );

	t.end();
});
